.include "rhun.inc"
.bss
.p2align 3
out: .zero SB_SIZE
.text
# check(doc, text, len, pairs, count) -> bool, comparing all oriented selections.
check:
    PROLOGUE 32
    mov rbx, rdi
    mov r12, rsi
    mov r13, rdx
    mov r14, rcx
    mov r15, r8
    call doc_len
    cmp rax, r13
    jne .Lcheck_bad
    lea rdi, [r13 + 1]
    call mem_alloc
    mov [rsp], rax
    mov rdi, rbx
    xor esi, esi
    mov rdx, r13
    mov rcx, rax
    call doc_copy
    mov rdi, [rsp]
    mov rsi, r12
    mov rdx, r13
    call memeq
    mov [rsp + 8], rax
    mov rdi, [rsp]
    call mem_free
    cmp qword ptr [rsp + 8], 0
    je .Lcheck_bad
    mov rdi, rbx
    call doc_selections_count
    cmp rax, r15
    jne .Lcheck_bad
    mov qword ptr [rsp + 16], 0
1:  mov rsi, [rsp + 16]
    cmp rsi, r15
    jae .Lcheck_ok
    mov rdi, rbx
    call doc_selections_get
    test r8d, r8d
    jz .Lcheck_bad
    cmp rax, [r14 + DMP_cur]
    jne .Lcheck_bad
    cmp rdx, [r14 + DMP_anchor]
    jne .Lcheck_bad
    add r14, DMP_SIZE
    inc qword ptr [rsp + 16]
    jmp 1b
.Lcheck_ok:
    mov eax, 1
    EPILOGUE
.Lcheck_bad:
    xor eax, eax
    EPILOGUE

FN main
    PROLOGUE 64
    mov r15, [rip + g_mem_live]
    lea r12, [rip + vectors]
    mov r13d, 1
.Lcase:
    cmp qword ptr [r12], 0
    je .Lpayloads
    call doc_new
    mov rbx, rax
    mov [rip + g_doc], rax
    mov rdi, rbx
    xor esi, esi
    mov rdx, [r12]
    mov rcx, [r12 + 8]
    xor r8d, r8d
    call doc_insert
    # Keep a real redo record so every rejected operation must preserve it.
    mov rdi, rbx
    mov rsi, [r12 + 8]
    lea rdx, [rip + letter]
    mov ecx, 1
    xor r8d, r8d
    call doc_insert
    mov rdi, rbx
    call doc_undo
    mov rdi, rbx
    mov rsi, [r12 + 16]
    mov rdx, [r12 + 24]
    call doc_selections_set
    cmp eax, 1
    jne failed
    mov eax, [r12 + 32]
    mov [rip + g_insert_spaces], eax
    mov eax, [r12 + 40]
    mov [rip + g_tab_width], eax
    mov qword ptr [rsp + 24], 0
    cmp qword ptr [r12 + 104], 0
    je .Lno_snippet
    mov rdi, [r12]
    mov rsi, [r12 + 8]
    call snippet_new
    mov r14, rax
    mov rdi, rax
    mov esi, 1
    xor edx, edx
    xor ecx, ecx
    xor r8d, r8d
    call snippet_add
    mov rdi, r14
    call snippet_validate
    cmp eax, 1
    jne failed
    mov rdi, rbx
    mov rsi, r14
    xor edx, edx
    call snippet_attach
    mov rdi, rbx
    mov rsi, [r12 + 16]
    mov rdx, [r12 + 24]
    call doc_selections_set
    mov rdi, r14
    mov esi, SN_SIZE
    call mem_dup
    mov [rsp + 24], rax
.Lno_snippet:
    cmp qword ptr [r12 + 48], 0
    je 1f
    mov rdi, rbx
    lea rsi, [rip + grammar]
    call doc_set_grammar
1:  test qword ptr [r12 + 112], 1
    jz 2f
    or dword ptr [rbx + DOC_flags], DF_READONLY
2:  test qword ptr [r12 + 112], 2
    jz 3f
    mov qword ptr [rbx + DOC_selectionbatch], -1
3:  test qword ptr [r12 + 112], 4
    jz 4f
    mov qword ptr [rip + g_doc], 0
4:  test qword ptr [r12 + 112], 8
    jz 5f
    mov qword ptr [rbx + DOC_cur], 1
5:  test qword ptr [r12 + 112], 16
    jz 6f
    mov rdi, rbx
    call doc_begin_group
6:  mov rdi, rbx
    mov esi, DOC_SIZE
    call mem_dup
    mov [rsp], rax
    mov rdi, rbx
    mov rsi, [r12 + 88]
    mov rdx, [r12 + 96]
    call editor_multi_newline_limited
    cmp rdx, [r12 + 104]
    jne failed
    cmp qword ptr [r12 + 104], 0
    je .Lsuccess
    test eax, eax
    jnz failed
    mov rdi, rbx
    mov rsi, [rsp]
    mov edx, DOC_SIZE
    call memeq
    test eax, eax
    jz failed
    mov rdi, [rbx + DOC_snippet]
    mov rsi, [rsp + 24]
    mov edx, SN_SIZE
    call memeq
    test eax, eax
    jz failed
    jmp .Lfree
.Lsuccess:
    cmp eax, 1
    jne failed
    mov rdi, rbx
    mov rsi, [r12 + 56]
    mov rdx, [r12 + 64]
    mov rcx, [r12 + 72]
    mov r8, [r12 + 80]
    call check
    test eax, eax
    jz failed
    test qword ptr [r12 + 112], 16
    jz 1f
    test dword ptr [rbx + DOC_flags], DF_GROUP
    jz failed
    mov rdi, rbx
    call doc_end_group
1:  mov r14d, 3
.Lreplay:
    mov rdi, rbx
    call doc_undo
    cmp eax, 1
    jne failed
    mov rdi, rbx
    mov rsi, [r12]
    mov rdx, [r12 + 8]
    mov rcx, [r12 + 16]
    mov r8, [r12 + 24]
    call check
    test eax, eax
    jz failed
    mov rdi, rbx
    call doc_redo
    cmp eax, 1
    jne failed
    mov rdi, rbx
    mov rsi, [r12 + 56]
    mov rdx, [r12 + 64]
    mov rcx, [r12 + 72]
    mov r8, [r12 + 80]
    call check
    test eax, eax
    jz failed
    dec r14
    jnz .Lreplay
    # Exercise the UI entry, including the paired-delimiter regression.
    cmp qword ptr [r12 + 24], 1
    jbe .Lfree
    mov rdi, rbx
    call doc_undo
    call ed_newline
    mov rdi, rbx
    mov rsi, [r12 + 56]
    mov rdx, [r12 + 64]
    mov rcx, [r12 + 72]
    mov r8, [r12 + 80]
    call check
    test eax, eax
    jz failed
    # Verify the entry's actual final snapshot, rather than only the planner's.
    mov rdi, rbx
    call doc_undo
    mov rdi, rbx
    call doc_redo
    mov rdi, rbx
    mov rsi, [r12 + 56]
    mov rdx, [r12 + 64]
    mov rcx, [r12 + 72]
    mov r8, [r12 + 80]
    call check
    test eax, eax
    jz failed
.Lfree:
    mov rdi, [rsp + 24]
    call mem_free
    mov rdi, [rsp]
    call mem_free
    mov qword ptr [rbx + DOC_selectionbatch], 0
    mov rdi, rbx
    call doc_free
    mov qword ptr [rip + g_doc], 0
    cmp r15, [rip + g_mem_live]
    jne failed
    add r12, 120
    inc r13
    jmp .Lcase
.Lpayloads:
    call doc_new
    mov rbx, rax
    mov rdi, rbx
    xor esi, esi
    lea rdx, [rip + pure_source]
    mov ecx, 4
    xor r8d, r8d
    call doc_insert
    mov dword ptr [rip + g_insert_spaces], 1
    mov dword ptr [rip + g_tab_width], 4
    mov rdi, rbx
    mov esi, DOC_SIZE
    call mem_dup
    mov [rsp], rax
    lea r12, [rip + budgets]
    mov r13d, 100
.Lbudget:
    cmp qword ptr [r12], -1
    je .Ldone
    mov rax, [r12 + 8]
    mov [rsp + 8], rax
    mov rdi, rbx
    mov esi, 3
    mov edx, 3
    mov rcx, [r12]
    lea r8, [rsp + 8]
    call editor_newline_payload
    cmp r8, [r12 + 16]
    jne failed
    test r8d, r8d
    jnz .Lpayload_error
    test rax, rax
    jz failed
    cmp rdx, 10
    jne failed
    cmp rcx, 7
    jne failed
    mov [rsp + 16], rax
    mov rdi, rax
    lea rsi, [rip + pure_result]
    mov edx, 10
    call memeq
    test eax, eax
    jz failed
    mov rdi, [rsp + 16]
    call mem_free
    jmp .Lpure_unchanged
.Lpayload_error:
    test rax, rax
    jnz failed
.Lpure_unchanged:
    mov rdi, rbx
    mov rsi, [rsp]
    mov edx, DOC_SIZE
    call memeq
    test eax, eax
    jz failed
    add r12, 24
    inc r13
    jmp .Lbudget
.Ldone:
    mov rdi, [rsp]
    call mem_free
    mov rdi, rbx
    call doc_free
    cmp r15, [rip + g_mem_live]
    jne failed
    lea rdi, [rip + ok]
    call log_cstr
    xor eax, eax
    EPILOGUE
failed:
    lea rdi, [rip + fail]
    call log_cstr
    lea rdi, [rip + out]
    mov rsi, r13
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 10
    call sb_push_byte
    mov rdi, [rip + out + SB_ptr]
    mov rsi, [rip + out + SB_len]
    call log_write
    mov eax, 1
    EPILOGUE
.section .rodata
ok: .asciz "ok editor multiple newline\n"
fail: .asciz "failed editor multiple newline case "
letter: .byte 88
pure_source: .ascii "  {}"
pure_result: .ascii "\n      \n  "
budgets: .quad 10,4,0, 9,4,2, 10,3,2, 0,4,2, 67108865,4,2, -1,0,0
.p2align 3
grammar: .zero GR_flags
    .quad GF_COLON
    .zero GR_SIZE-GR_flags-8
vectors:
    # paired regression
    .quad v0s,5,v0p,2,1,4,0,v0r,17,v0a,2,67108864,67108864,0,0
    # primary last
    .quad v1s,5,v1p,2,1,4,0,v1r,17,v1a,2,67108864,67108864,0,0
    # empty duplicate
    .quad v2s,0,v2p,2,1,4,0,v2r,1,v2a,1,67108864,67108864,0,0
    # plain
    .quad v3s,7,v3p,2,1,4,0,v3r,9,v3a,2,67108864,67108864,0,0
    # reversed selected
    .quad v4s,5,v4p,2,1,4,0,v4r,3,v4a,2,67108864,67108864,0,0
    # overlap
    .quad v5s,4,v5p,2,1,4,0,v5r,1,v5a,1,67108864,67108864,0,0
    # adjacent ranges
    .quad v6s,4,v6p,2,1,4,0,v6r,2,v6a,2,67108864,67108864,0,0
    # truncated indent
    .quad v7s,9,v7p,2,1,4,0,v7r,15,v7a,2,67108864,67108864,0,0
